export const WAVE_RUNTIME_HTML = "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no\"><style>html,body{margin:0;width:100%;height:100%;background:#000;overflow:hidden}#ekwave-host{position:absolute;inset:0}/* Ekalight flowing-wave background — styles. Classes prefixed .ekwave-*.\n   The host element you mount into should be positioned (absolute/relative) and sized. */\n\n.ekwave-bg {\n  position: absolute;\n  left: 50%; top: 50%;\n  /* width/height/margins are set by JS (3× backing surface) */\n  background-position: center;\n  background-size: contain;\n  background-repeat: no-repeat;\n  transform-origin: center center;\n  will-change: transform;\n}\n.ekwave-layer2 {\n  mix-blend-mode: lighten;   /* white dots glow where the two layers overlap */\n  opacity: 0.7;\n}\n\n/* soft top/bottom fade to black — hides the image edges & ripple seams */\n.ekwave-fade {\n  position: absolute; inset: 0; pointer-events: none; z-index: 1;\n  background: linear-gradient(to bottom,\n    #000 0%, rgba(0,0,0,0) 24%, rgba(0,0,0,0) 76%, #000 100%);\n}\n</style></head><body><div id=\"ekwave-host\"></div><script>/* Ekalight flowing-wave background — vanilla JS, framework-agnostic.\n *\n *   <link rel=\"stylesheet\" href=\"wave-bg.css\">\n *   <div id=\"bg\" style=\"position:absolute; inset:0\"></div>\n *   <script src=\"wave-bg.js\"></script>\n *   <script>EkalightWaveBG.mount('#bg');</script>\n *\n * Renders a full-bleed, continuously-flowing halftone wave (white dots on black).\n * Two layers weave together and never fully separate. Motion is a sum of sines at\n * incommensurate frequencies, so it NEVER repeats. An SVG displacement filter makes\n * the dots ripple like water; it renders on a 3× backing surface => razor sharp.\n *\n * mount(target, options):\n *   target            CSS selector or element (its box is filled; should be positioned)\n *   options.image     wave image URL (default 'assets/halftone-white.png')\n *   options.speed     global pace multiplier (default 4.0)\n *   options.frame     [w,h] design frame the 3× backing is sized from (default [393,852])\n *   options.zoom      base scale of the wave (default 0.60; higher = more zoomed-in)\n *\n * Honors prefers-reduced-motion (renders a still frame). Returns a handle with .stop().\n */\n(function () {\n  var NS = 'http://www.w3.org/2000/svg';\n  var uid = 0;\n\n  function el(tag, attrs) {\n    var e = document.createElementNS(NS, tag);\n    for (var k in attrs) e.setAttribute(k, attrs[k]);\n    return e;\n  }\n\n  function mount(target, options) {\n    options = options || {};\n    var host = typeof target === 'string' ? document.querySelector(target) : target;\n    if (!host) throw new Error('EkalightWaveBG: target not found');\n    var image = options.image || 'assets/halftone-white.png';\n    var speed = options.speed != null ? options.speed : 4.0;\n    var frame = options.frame || [393, 852];\n    var zoom = options.zoom != null ? options.zoom : 0.60;\n    var id = 'ekwave' + (++uid);\n\n    // 3× backing => the displacement filter rasterizes at high resolution (sharp)\n    var bw = frame[0] * 3, bh = frame[1] * 3;\n\n    host.style.overflow = 'hidden';\n    host.style.background = '#000';\n    host.innerHTML =\n      '<div class=\"ekwave-bg\" id=\"' + id + '-1\" style=\"background-image:url(\\'' + image + '\\')\"></div>' +\n      '<div class=\"ekwave-bg ekwave-layer2\" id=\"' + id + '-2\" style=\"background-image:url(\\'' + image + '\\')\"></div>' +\n      '<div class=\"ekwave-fade\"></div>';\n\n    [host.children[0], host.children[1]].forEach(function (b) {\n      b.style.width = bw + 'px'; b.style.height = bh + 'px';\n      b.style.marginLeft = (-bw / 2) + 'px'; b.style.marginTop = (-bh / 2) + 'px';\n    });\n\n    // two displacement filters\n    var svg = el('svg', { width: 0, height: 0, 'aria-hidden': 'true' });\n    svg.setAttribute('style', 'position:absolute');\n    function makeFilter(fid, bf, seed, scale) {\n      var f = el('filter', { id: fid, x: '-25%', y: '-25%', width: '150%', height: '150%' });\n      var turb = el('feTurbulence', { type: 'fractalNoise', baseFrequency: bf, numOctaves: 3, seed: seed, result: 'n' + fid });\n      var disp = el('feDisplacementMap', { in: 'SourceGraphic', in2: 'n' + fid, scale: scale, xChannelSelector: 'R', yChannelSelector: 'G' });\n      f.appendChild(turb); f.appendChild(disp); svg.appendChild(f);\n      return { turb: turb, disp: disp };\n    }\n    var F1 = makeFilter(id + '-f1', '0.006 0.011', 6, 26);\n    var F2 = makeFilter(id + '-f2', '0.005 0.010', 19, 24);\n    document.body.appendChild(svg);\n    host.children[0].style.filter = 'url(#' + id + '-f1)';\n    host.children[1].style.filter = 'url(#' + id + '-f2)';\n\n    var bg1 = host.children[0], bg2 = host.children[1];\n\n    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {\n      bg1.style.transform = 'scale(' + (-zoom) + ',' + (zoom * 0.72) + ')';\n      bg2.style.transform = 'scale(' + zoom + ',' + (zoom * 0.72) + ')';\n      return { stop: function () {} };\n    }\n\n    function osc(t, terms) {\n      var v = 0;\n      for (var i = 0; i < terms.length; i++) v += terms[i][0] * Math.sin(t * terms[i][1] + terms[i][2]);\n      return v;\n    }\n\n    var raf;\n    function frameFn(now) {\n      var t = now / 1000 * speed;\n\n      // layer 1 — rides just below center, gently angled, h-mirrored & slimmed\n      var tx1 = osc(t, [[1.2, 0.052, 0.0], [0.7, 0.031, 1.7], [0.4, 0.087, 0.9]]);\n      var ty1 = 1.3 + osc(t, [[0.6, 0.041, 2.3], [0.4, 0.024, 0.4], [0.25, 0.069, 2.1]]);\n      var rot1 = 4 + osc(t, [[0.9, 0.037, 0.9], [0.5, 0.022, 2.8]]);\n      var sk1 = osc(t, [[1.5, 0.029, 0.6], [0.9, 0.048, 2.2]]);\n      var sc1 = zoom + osc(t, [[0.012, 0.045, 1.1], [0.008, 0.027, 0.2]]);\n      bg1.style.transform = 'translate(' + tx1.toFixed(3) + '%,' + ty1.toFixed(3) + '%) rotate(' + rot1.toFixed(3) + 'deg) skewX(' + sk1.toFixed(3) + 'deg) scale(' + (-sc1).toFixed(4) + ',' + (sc1 * 0.72).toFixed(4) + ')';\n\n      // layer 2 — rides just above center, counter-angled => pair never parts\n      var tx2 = osc(t, [[1.1, 0.039, 3.1], [0.65, 0.025, 0.7], [0.35, 0.071, 2.4]]);\n      var ty2 = -1.3 + osc(t, [[0.6, 0.034, 1.2], [0.4, 0.020, 2.5], [0.25, 0.058, 0.6]]);\n      var rot2 = -4 + osc(t, [[0.8, 0.030, 2.0], [0.5, 0.018, 0.5]]);\n      var sk2 = osc(t, [[1.3, 0.024, 2.0], [0.8, 0.041, 0.3]]);\n      var sc2 = (zoom + 0.01) + osc(t, [[0.011, 0.036, 0.6], [0.007, 0.022, 2.2]]);\n      bg2.style.transform = 'translate(' + tx2.toFixed(3) + '%,' + ty2.toFixed(3) + '%) rotate(' + rot2.toFixed(3) + 'deg) skewX(' + sk2.toFixed(3) + 'deg) scale(' + sc2.toFixed(4) + ',' + (sc2 * 0.72).toFixed(4) + ')';\n\n      // ripple depth — swells & surges like light on water\n      F1.disp.setAttribute('scale', (24 + osc(t, [[8, 0.061, 0.3], [5, 0.034, 1.9], [3, 0.094, 0.7]])).toFixed(2));\n      F2.disp.setAttribute('scale', (22 + osc(t, [[7, 0.050, 2.4], [5, 0.029, 0.8], [3, 0.080, 1.5]])).toFixed(2));\n\n      // turbulence field morphs & slides => traveling-water character\n      F1.turb.setAttribute('baseFrequency',\n        (0.0066 + 0.0018 * Math.sin(t * 0.021 + 0.5)).toFixed(5) + ' ' + (0.0104 + 0.0026 * Math.sin(t * 0.028 + 1.8)).toFixed(5));\n      F2.turb.setAttribute('baseFrequency',\n        (0.0056 + 0.0015 * Math.sin(t * 0.017 + 2.2)).toFixed(5) + ' ' + (0.0098 + 0.0022 * Math.sin(t * 0.024 + 0.3)).toFixed(5));\n\n      raf = requestAnimationFrame(frameFn);\n    }\n    raf = requestAnimationFrame(frameFn);\n\n    return { stop: function () { cancelAnimationFrame(raf); if (svg.parentNode) svg.parentNode.removeChild(svg); } };\n  }\n\n  window.EkalightWaveBG = { mount: mount };\n})();\n</script><script>EkalightWaveBG.mount(\"#ekwave-host\",{image:\"data:image/png;base64,\",frame:[393,280],zoom:0.62,speed:4.0});</script></body></html>";
